isDisabled:
{{
  (function() {
    const machines = sel_loc_machine.selectedOptionValues || [];
    if (!sel_loc_client.selectedOptionValue || machines.length === 0 || !dat_loc_debut.selectedDate || !sel_loc_duree.selectedOptionValue) {
      return true;
    }

    const dureeChoisie = sel_loc_duree.selectedOptionValue;
    const resas = Get_Calendar_Events_Machine.data || [];
    const dateDebutStr = moment(dat_loc_debut.selectedDate).format("YYYY-MM-DD");

    // --- GESTION MULTI-JOURS ---
    if (dureeChoisie === 'Multi_Jours') {
      if (!dat_loc_fin.selectedDate) return true; 

      const dateFinStr = moment(dat_loc_fin.selectedDate).format("YYYY-MM-DD");
      if (dateFinStr < dateDebutStr) return true; 

      const conflitMulti = resas.some(r => {
        const dateResa = moment(r.Date_Location).format("YYYY-MM-DD");
        return dateResa >= dateDebutStr && dateResa <= dateFinStr;
      });

      return conflitMulti; 
    }

    // --- GESTION CLASSIQUE (1 Journée / Matin / Aprem) ---
    const resasDuJour = resas.filter(r => moment(r.Date_Location).format("YYYY-MM-DD") === dateDebutStr);
    if (resasDuJour.length === 0) return false;

    const aMatin = resasDuJour.some(r => ['Matin', 'Journee', 'Multi_Jours', 'Journee_Demi'].includes(r.Type_Duree));
    const aAprem = resasDuJour.some(r => ['Apres_Midi', 'Journee', 'Multi_Jours', 'Journee_Demi'].includes(r.Type_Duree));

    if (dureeChoisie === 'Journee') return resasDuJour.length > 0;
    if (dureeChoisie === 'Matin') return aMatin;
    if (dureeChoisie === 'Apres_Midi') return aAprem;

    return false;
  })()
}}

onClick:
{{
  Insert_Location.run()
    .then(async () => {
      // 1. Ferme la fenêtre immédiatement pour fluidifier l'expérience
      closeModal('modal_add_location');

      // 2. Affiche un message de succès
      showAlert('Location(s) créée(s) avec succès !', 'success');

      // 3. Rafraîchit les contrats ET l'agenda, puis met le cache à jour
      await Cache_Location.initialiserPage();
    })
    .catch((err) => {
      // En cas d'erreur
      showAlert("Erreur lors de la création : " + err.message, 'error');
    });
}}
